    title: "SMOTE tạo ra một điểm nằm giữa, không tạo ra một khách hàng",
    see: "Hình này thể hiện SMOTE. Thuật toán nội suy giữa các dòng thuộc lớp thiểu số trong không gian các cột số, và điểm mới không phải một người đã mua. Nếu làm SMOTE trước khi chia tập, một điểm nằm giữa có thể mang một phần của tập học và một phần của tập chấm, đó là rò rỉ dữ liệu.",
